from functools import lru_cache


def count_tilings(grid: list[str]) -> int:
    if not isinstance(grid, list):
        raise TypeError

    if not grid:
        return 1

    m = len(grid[0])
    for row in grid:
        if not isinstance(row, str):
            raise TypeError
        if len(row) != m:
            raise ValueError
        for ch in row:
            if ch != "." and ch != "#":
                raise ValueError

    if m == 0:
        return 1

    h = len(grid)

    # Work with the smaller side as the profile width (at most 10 by spec).
    if m > h and h <= 10:
        grid = ["".join(grid[r][c] for r in range(h)) for c in range(m)]
        h, m = m, h

    flat = "".join(grid)
    n_cells = h * m

    # A frontier of length m + 2 is sufficient:
    # from the first empty cell, pieces can reach at most offset m + 1.
    w2 = m + 2
    full = (1 << w2) - 1

    init = 0
    for j in range(w2):
        if j >= n_cells or flat[j] == "#":
            init |= 1 << j

    @lru_cache(maxsize=None)
    def advance(mask: int, pos: int) -> dict[int, int]:
        if pos == n_cells:
            return {full: 1} if mask == full else {}

        # Bit 0 is the current cell. If it is blocked/already occupied, skip it.
        if mask & 1:
            shifted = mask >> 1
            add_pos = pos + w2
            if add_pos >= n_cells or flat[add_pos] == "#":
                shifted |= 1 << (w2 - 1)
            return {shifted: 1}

        row = pos // m
        col = pos % m
        res: dict[int, int] = {}

        def add_state(new_mask: int) -> None:
            shifted = new_mask >> 1
            add_pos = pos + w2
            if add_pos >= n_cells or flat[add_pos] == "#":
                shifted |= 1 << (w2 - 1)
            res[shifted] = res.get(shifted, 0) + 1

        # Horizontal domino.
        if col + 1 < m:
            b1 = 2
            if not (mask & b1):
                add_state(mask | 1 | b1)

        # Vertical domino.
        bW = 1 << m
        if not (mask & bW):
            add_state(mask | 1 | bW)

        # L trominoes.
        if row + 1 < h:
            # Top-left corner of the 2x2 block: cells pos, pos+1, pos+m, pos+m+1.
            if col + 1 < m:
                b1 = 2
                bW = 1 << m
                bW1 = 1 << (m + 1)

                # Missing top-right: covers current, bottom-left, bottom-right.
                if not (mask & bW) and not (mask & bW1):
                    add_state(mask | 1 | bW | bW1)

                # Missing bottom-left: covers current, top-right, bottom-right.
                if not (mask & b1) and not (mask & bW1):
                    add_state(mask | 1 | b1 | bW1)

                # Missing bottom-right: covers current, top-right, bottom-left.
                if not (mask & b1) and not (mask & bW):
                    add_state(mask | 1 | b1 | bW)

            # Top-right corner of the 2x2 block: cells pos, pos-1, pos+m-1, pos+m.
            # The top-left cell is missing and must already be filled/skipped.
            if col > 0:
                bm1 = 1 << (m - 1)
                bW = 1 << m
                if not (mask & bm1) and not (mask & bW):
                    add_state(mask | 1 | bm1 | bW)

        return res

    dp = {init: 1}
    for pos in range(n_cells):
        ndp: dict[int, int] = {}
        for mask, cnt in dp.items():
            for nxt, mult in advance(mask, pos).items():
                if mult:
                    ndp[nxt] = ndp.get(nxt, 0) + cnt * mult
        dp = ndp
        if not dp:
            return 0

    return dp.get(full, 0)
